@Component("complianceProgram-handler")
@ProcessingGroup("complianceProgram-processing-group")
public class ComplianceProgramEventHandler {
	
	// core constructor
	ComplianceProgramEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateComplianceProgramEvent
     */
    @EventHandler
    public void handle( CreateComplianceProgramEvent event) {
        entityManager.persist(new ComplianceProgram(event.getComplianceProgramId(), event.getName(), event.getFramework(), event.getOrganization(), event.getRequirements(), event.getControls(), event.getAttestations(), event.getRegulations(), event.getStatus()));
    }

    /*
     * @param	event UpdateComplianceProgramEvent
     */
    @EventHandler
    public ComplianceProgram handle( UpdateComplianceProgramEvent event) {
    	entityManager.merge(new ComplianceProgram(event.getComplianceProgramId(), event.getName(), event.getFramework(), event.getOrganization(), event.getRequirements(), event.getControls(), event.getAttestations(), event.getRegulations(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteComplianceProgramEvent
     */
    @EventHandler
    public void on( DeleteComplianceProgramEvent event) {
    	ComplianceProgram entity = new ComplianceProgram();
   
    	// ------------------------------------------
    	// apply the ComplianceProgramId
    	// ------------------------------------------
    	entity.setComplianceProgramId( event.getComplianceProgramId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ComplianceProgramRepository complianceProgramEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ComplianceProgramEventHandler.class.getName());

}
